import re
from datetime import datetime

_DIGITS = "0123456789"
_GMAIL_DOMAINS = ("gmail.com", "googlemail.com")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_ZIP_PLUS4 = re.compile(r"[0-9]{4,5}-[0-9]{4}")
_TAG_SPLIT = re.compile(r"[;,]")


def _all_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _norm_email(raw):
    s = raw
    lt = s.find("<")
    if lt != -1:
        gt = s.find(">", lt + 1)
        if gt != -1:
            s = s[lt + 1:gt]
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _email_is_valid(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _norm_phone(raw):
    s = raw.lower()
    cut = len(s)
    for marker in ("x", "ext", "#"):
        pos = s.find(marker)
        if pos != -1:
            cut = min(cut, pos)
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _phone_is_valid(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _norm_zip(raw):
    s = raw.strip()
    if _ZIP_PLUS4.fullmatch(s):
        s = s.split("-", 1)[0]
    if len(s) == 4 and _all_digits(s):
        s = "0" + s
    return s if len(s) == 5 and _all_digits(s) else ""


def _norm_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _norm_tags(raw):
    return {t.strip().lower() for t in _TAG_SPLIT.split(raw) if t.strip()}


def _pick(people, members, field):
    """Return the preferred record in `members` where `field` is non-empty, or None.
    `members` must be in input order. Preference: manual source, then most recent
    `updated`, then earliest input row (sorts are stable, so ties keep input order)."""
    cands = [i for i in members if people[i][field]]
    if not cands:
        return None
    cands.sort(key=lambda i: people[i]["updated"], reverse=True)
    cands.sort(key=lambda i: not people[i]["manual"])
    return people[cands[0]]


def _value(people, members, field):
    rec = _pick(people, members, field)
    return rec[field] if rec is not None else ""


def dedupe_contacts(rows):
    # Normalize each row and drop rows with neither a valid email nor a valid phone.
    people = []
    for row in rows:
        email = _norm_email(row.get("email", ""))
        phone = _norm_phone(row.get("phone", ""))
        email_ok = _email_is_valid(email)
        phone_ok = _phone_is_valid(phone)
        if not (email_ok or phone_ok):
            continue
        source = row.get("source", "").strip().lower()
        people.append({
            "first": _norm_name(row.get("first_name", "")),
            "last": _norm_name(row.get("last_name", "")),
            "zip": _norm_zip(row.get("zip", "")),
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "source": source,
            "manual": source == "manual",
            "updated": _parse_updated(row.get("updated", "")),
            "tags": _norm_tags(row.get("tags", "")),
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
        })

    # Union-find: same valid email, or same valid phone + same non-empty last name.
    parent = list(range(len(people)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_by_email = {}
    first_by_phone = {}
    for i, p in enumerate(people):
        if p["email"]:
            if p["email"] in first_by_email:
                union(first_by_email[p["email"]], i)
            else:
                first_by_email[p["email"]] = i
        if p["phone"] and p["last"]:
            key = (p["phone"], p["last"].casefold())
            if key in first_by_phone:
                union(first_by_phone[key], i)
            else:
                first_by_phone[key] = i

    # Group rows; dict order is each group's earliest input row.
    groups = {}
    for i in range(len(people)):
        groups.setdefault(find(i), []).append(i)

    out = []
    for members in groups.values():
        latest = max(people[i]["updated"] for i in members)
        tags = set().union(*(people[i]["tags"] for i in members))
        out.append({
            "first_name": _value(people, members, "first"),
            "last_name": _value(people, members, "last"),
            "zip": _value(people, members, "zip"),
            "email": _value(people, members, "email"),
            "phone": _value(people, members, "phone"),
            "source": _value(people, members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(people[i]["opted_out"] for i in members) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })
    return out
